<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Revoke;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKeyRef;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Service\Visibility\UserPersonalApiKeyVisibilityService;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserPersonalApiKeyRevokeUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserPersonalApiKeyVisibilityService $visibility,
        private readonly UserPersonalApiKeyWriteGateway $writer,
    ) {
    }

    public function allowRevoke(?UserPersonalApiKeyRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Revoke usecase for User personal api key");
        $span = $this->startSpan("Check allow of Revoke usecase for User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyRevokeAllowDecision(Allow::allowed('revoke', 'Allowed to User personal api key by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function revoke(string $uid): UserPersonalApiKeyRevokeResult
    {
        $this->logDebug("Run Revoke usecase for User personal api key");
        $span = $this->startSpan("Run Revoke usecase for User personal api key");
        try {
            $ref = new UserPersonalApiKeyRef($uid);
            $allow = $this->allowRevoke($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Revoke User personal api key');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new UserPersonalApiKeyRevokeCheck($original));
            $modified = $original->revoke();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserPersonalApiKeyRevokeResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
